<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import {Bold,Italic,Underline,AlignLeft,AlignCenter,AlignRight} from 'lucide-vue-next';import FontSelect from './FontSelect.vue';
import {setTextDirection} from '../../shared/text-style.mjs';
defineProps({model:{type:Object,required:true}});
</script>
<template><div class="text-formatting"><label>{{ui("字体")}}<FontSelect v-model="model.fontFamily"/></label><label class="font-direction-field">{{ui("文字方向")}}<select :aria-label="ui(&quot;文字方向&quot;)" :value="model.vertical?'vertical':'horizontal'" @change="setTextDirection(model,$event.target.value==='vertical')"><option value="horizontal">{{ui("横向")}}</option><option value="vertical">{{ui("竖向")}}</option></select></label><div class="text-formatting-tools" role="group" :aria-label="ui(&quot;文字样式&quot;)"><button type="button" :title="ui(&quot;粗体&quot;)" :aria-label="ui(&quot;粗体&quot;)" :aria-pressed="model.fontWeight>=600" @click="model.fontWeight=model.fontWeight>=600?400:700"><Bold :size="15"/></button><button type="button" :title="ui(&quot;斜体&quot;)" :aria-label="ui(&quot;斜体&quot;)" :aria-pressed="model.fontStyle==='italic'" @click="model.fontStyle=model.fontStyle==='italic'?'normal':'italic'"><Italic :size="15"/></button><button type="button" :title="ui(&quot;下划线&quot;)" :aria-label="ui(&quot;下划线&quot;)" :aria-pressed="model.textDecoration==='underline'" @click="model.textDecoration=model.textDecoration==='underline'?'none':'underline'"><Underline :size="15"/></button><span/><button v-for="alignment in [{id:'left',name:'左对齐',icon:AlignLeft},{id:'center',name:'居中对齐',icon:AlignCenter},{id:'right',name:'右对齐',icon:AlignRight}]" type="button" :title="ui(alignment.name)" :aria-label="ui(alignment.name)" :aria-pressed="(model.textAlign||'center')===alignment.id" @click="model.textAlign=alignment.id"><component :is="alignment.icon" :size="15"/></button></div></div></template>
